// Longbridge official MCP (Streamable HTTP) adapter. Read-only: account + portfolio
// + cash flow. Docs: https://open.longbridge.com/zh-CN/docs/mcp
// - Main service: https://mcp.longbridge.com/mcp (Bearer token required)
// - Agent authorization endpoint: https://mcp.longbridge.com/agent — before auth it
//   only exposes the `authenticate` tool; exchanging a one-time code returns the
//   Bearer token used afterwards. Codes are generated by the user at
//   https://open.longbridge.com/connect and expire in 10 minutes.
import { createHash, randomUUID } from 'node:crypto'
import { cashSignOf, isFlowKind, canonicalMarket, marketCurrency } from './model.mjs'

const DEFAULT_ENDPOINT = 'https://mcp.longbridge.com'
const PROTOCOL_VERSION = '2025-11-25'
const CLIENT_NAME = 'dsh-wealth'
const fail = (message) => { throw new Error(message) }

function text(value, field) {
  if (typeof value !== 'string' || !value.trim()) fail(`${field} is required`)
  return value.trim()
}
function numeric(value, field, { signed = false, positive = false } = {}) {
  if ((typeof value !== 'number' && typeof value !== 'string') || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(String(value))) fail(`${field} is unknown or invalid`)
  const n = Number(value)
  if (!Number.isFinite(n)) fail(`${field} is not finite`)
  if (!signed && n < 0) fail(`${field} is negative`)
  if (positive && !(n > 0)) fail(`${field} must be positive`)
  return n
}
function money(value, field) {
  // Longbridge MCP balances arrive as decimal strings; keep them exact.
  if (value == null || value === '') return null
  if (typeof value === 'object') {
    if (typeof value.toString === 'function') value = value.toString()
    else fail(`${field} is invalid`)
  }
  return numeric(value, field)
}
function currency(value, field = 'currency') {
  const c = text(value, field).toUpperCase()
  if (!/^[A-Z]{3}$/.test(c)) fail(`${field} must be a three-letter currency`)
  return c
}
function day(value, field) {
  const d = /^\d{4}-\d{2}-\d{2}$/.exec(String(value || ''))
  if (!d || !Number.isFinite(Date.parse(d[0] + 'T00:00:00Z')) || new Date(d[0] + 'T00:00:00Z').toISOString().slice(0, 10) !== d[0]) fail(`${field} must be a valid YYYY-MM-DD date`)
  return d[0]
}
function instant(value, field) {
  const raw = String(value || '').trim()
  if (!raw || !Number.isFinite(Date.parse(raw))) fail(`${field} is not a valid timestamp`)
  const date = new Date(Date.parse(raw)), iso = date.toISOString()
  return { date: iso.slice(0, 10), time: iso.slice(11, 19) }
}
function array(value, field) { if (!Array.isArray(value)) fail(`${field} must be an array`); return value }

// symbol like 700.HK / AAPL.US / 600000.SH / 000001.SZ / D05.SG
function lbSymbol(raw, field = 'symbol') {
  const symbol = text(raw, field), match = /^([A-Za-z0-9._-]+)\.(HK|US|SH|SZ|SG)$/.exec(symbol)
  if (!match) fail(`Longbridge MCP returned an unsupported symbol: ${symbol}`)
  return { symbol, market: { HK: 'HK', US: 'US', SH: 'CN', SZ: 'CN', SG: 'SG' }[match[2]] }
}
function canonical(row) {
  // Every archived row must carry a kind from the canonical registry.
  if (!isFlowKind(row.kind)) fail(`Longbridge MCP returned an unmapped flow kind: ${row.kind}`)
  return {
    date: row.date, time: row.time || null, kind: row.kind, originalType: row.originalType || null,
    symbol: row.symbol || null, name: row.name || null, market: row.market || null, currency: row.currency,
    qty: row.qty ?? null, price: row.price ?? null, grossAmount: null,
    cashAmount: row.cashAmount ?? null, fee: row.fee ?? null, externalId: row.externalId ?? null, note: row.note || null,
  }
}
function dedupe(rows) {
  const seen = new Map()
  for (const row of rows) {
    const key = JSON.stringify([row.date, row.time, row.kind, row.symbol, row.currency, row.qty, row.price, row.cashAmount, row.fee, row.externalId])
    if (!seen.has(key)) seen.set(key, row)
  }
  return [...seen.values()].sort((a, b) => (a.date + (a.time || '')).localeCompare(b.date + (b.time || '')) || String(a.externalId).localeCompare(String(b.externalId)))
}

export const LONGLIDGE_MCP_DEFAULT_ENDPOINT = DEFAULT_ENDPOINT

/** Minimal MCP Streamable HTTP client: initialize, notifications/initialized, tools/call. */
export function createLongbridgeMcp({ secrets = {}, endpoint, signal, deps = {} } = {}) {
  const base = text(endpoint || DEFAULT_ENDPOINT, 'Longbridge MCP endpoint').replace(/\/+$/, '')
  if (base.endsWith('/agent')) fail('长桥授权端点 (/agent) 只用于兑换授权码，不能作为数据连接；请改用主服务地址')
  let token = text(secrets.mcpToken, 'Longbridge MCP token (mcpToken)')
  const fetchImpl = deps.fetch || globalThis.fetch
  const timeoutMs = deps.timeoutMs ?? 30000
  let sessionId = null, initialized = false, seq = 0
  const guard = () => { if (signal?.aborted) throw signal.reason ?? new Error('Longbridge MCP aborted') }

  async function rpc(method, params, { auth = true, timeout = timeoutMs } = {}) {
    guard()
    seq++
    const id = seq
    const body = { jsonrpc: '2.0', id, method, ...(params === undefined ? {} : { params }) }
    const headers = {
      'content-type': 'application/json',
      accept: 'application/json, text/event-stream',
      'mcp-protocol-version': PROTOCOL_VERSION,
    }
    if (auth && token) headers.authorization = 'Bearer ' + token
    if (sessionId) headers['mcp-session-id'] = sessionId
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(new Error('Longbridge MCP 请求超时')), timeout)
    const onAbort = () => controller.abort(signal.reason ?? new Error('Longbridge MCP aborted'))
    signal?.addEventListener('abort', onAbort, { once: true })
    let response
    try {
      guard()
      response = await fetchImpl(base + '/mcp', { method: 'POST', headers, body: JSON.stringify(body), signal: controller.signal, redirect: 'error' })
    } catch (error) {
      if (controller.signal.aborted && !signal?.aborted) fail('Longbridge MCP 请求超时')
      throw error
    } finally { clearTimeout(timer); signal?.removeEventListener('abort', onAbort) }
    const sid = response.headers.get('mcp-session-id')
    if (sid) sessionId = sid
    if (response.status === 401) fail('长桥 MCP 授权已失效或未授权，请重新生成授权码兑换 Token')
    if (response.status === 403) fail('长桥 MCP 拒绝访问：权限范围不足（需包含资产持仓流水只读权限），请在长桥账户安全设置中重新授权')
    if (!response.ok) fail('Longbridge MCP 返回 HTTP ' + response.status)
    const contentType = String(response.headers.get('content-type') || '')
    const payloadText = await response.text()
    guard()
    if (!payloadText.trim()) return null // notifications carry no body
    let payload
    if (contentType.includes('text/event-stream')) {
      // SSE frames: keep only the last data: line that carries a JSON-RPC response.
      const frames = payloadText.split(/\r?\n\r?\n/)
      let parsed = null
      for (const frame of frames) {
        for (const line of frame.split(/\r?\n/)) {
          if (!/^data:\s?/.test(line)) continue
          const raw = line.replace(/^data:\s?/, '').trim()
          if (!raw || raw === '[DONE]') continue
          try { const value = JSON.parse(raw); if (value && (value.id === id || value.method)) parsed = value } catch { /* keep last good */ }
        }
      }
      if (!parsed) fail('Longbridge MCP 返回了无法解析的 SSE 响应')
      payload = parsed
    } else {
      try { payload = JSON.parse(payloadText) } catch { fail('Longbridge MCP 返回了无法解析的响应') }
    }
    if (payload.error) {
      const detail = payload.error.message || 'unknown error'
      if (/scope/i.test(detail)) fail('长桥 MCP 权限不足（' + detail + '）：请在长桥授权页勾选资产持仓流水只读权限后重新授权')
      fail('Longbridge MCP 调用失败：' + detail)
    }
    return payload
  }

  async function ensureSession() {
    if (initialized) return
    const init = await rpc('initialize', { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: CLIENT_NAME, version: '0.7.0' } })
    if (!init?.result?.serverInfo) fail('Longbridge MCP 初始化失败：响应缺少 serverInfo')
    initialized = true
    await rpc('notifications/initialized', undefined, { auth: true, timeout: 8000 })
  }

  async function call(tool, args = {}) {
    guard()
    if (typeof tool !== 'string' || !tool.trim()) fail('Longbridge MCP tool name is required')
    await ensureSession()
    const response = await rpc('tools/call', { name: tool, arguments: args })
    const result = response?.result
    if (!result) fail('Longbridge MCP 工具调用没有返回结果')
    if (result.isError) {
      const content = Array.isArray(result.content) ? result.content : []
      const message = content.map(c => c?.text || '').join(' ') || 'tool reported an error'
      if (/授权|authoriz|token|401/i.test(message)) fail('长桥 MCP 授权已失效，请重新生成授权码并兑换 Token：' + message)
      fail('Longbridge MCP 工具 ' + tool + ' 失败：' + message)
    }
    if (result.structuredContent !== undefined && result.structuredContent !== null) return result.structuredContent
    const content = Array.isArray(result.content) ? result.content : []
    const first = content.find(c => typeof c?.text === 'string')
    if (!first) return null
    try { return JSON.parse(first.text) } catch { return first.text }
  }

  return {
    call,
    get endpoint() { return base },
    async dispose() { initialized = false; sessionId = null },
  }
}

/** Exchange a one-time agent authorization code for a Bearer token (POST /agent). */
export async function exchangeLongbridgeMcpCode(code, { endpoint, signal, deps = {} } = {}) {
  const oneTime = String(code || '').trim()
  if (!oneTime) fail('请填写长桥授权码（在 open.longbridge.com/connect 生成，10 分钟内有效）')
  const base = text(endpoint || DEFAULT_ENDPOINT, 'Longbridge MCP endpoint').replace(/\/+$/, '')
  const fetchImpl = deps.fetch || globalThis.fetch
  const timeoutMs = deps.timeoutMs ?? 30000
  const url = base + '/agent'
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error('Longbridge MCP 授权请求超时')), timeoutMs)
  const onAbort = () => controller.abort(signal.reason ?? new Error('Longbridge MCP aborted'))
  signal?.addEventListener('abort', onAbort, { once: true })
  let response
  try {
    // /agent is the pre-auth endpoint: initialize, call authenticate, return the token.
    const initBody = { jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: CLIENT_NAME, version: '0.7.0' } } }
    response = await fetchImpl(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
      body: JSON.stringify(initBody),
      signal: controller.signal, redirect: 'error',
    })
    if (!response.ok) fail('长桥授权端点返回 HTTP ' + response.status)
    const sid = response.headers.get('mcp-session-id')
    const contentType = String(response.headers.get('content-type') || '')
    const raw = await response.text()
    let payload
    if (contentType.includes('text/event-stream')) {
      const frames = raw.split(/\r?\n\r?\n/); payload = null
      for (const frame of frames) for (const line of frame.split(/\r?\n/)) {
        if (!/^data:\s?/.test(line)) continue
        const data = line.replace(/^data:\s?/, '').trim()
        if (!data) continue
        try { const v = JSON.parse(data); if (v && v.id === 1) payload = v } catch { /* keep */ }
      }
      if (!payload) fail('长桥授权端点返回了无法解析的 SSE 响应')
    } else {
      try { payload = JSON.parse(raw) } catch { fail('长桥授权端点返回了无法解析的响应') }
    }
    if (payload.error) fail('长桥授权初始化失败：' + (payload.error.message || 'unknown'))
    // authenticate tool call reuses the session header.
    const authBody = { jsonrpc: '2.0', id: 2, method: 'tools/call', params: { name: 'authenticate', arguments: { code: oneTime } } }
    const authResponse = await fetchImpl(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream', ...(sid ? { 'mcp-session-id': sid } : {}) },
      body: JSON.stringify(authBody),
      signal: controller.signal, redirect: 'error',
    })
    if (!authResponse.ok) fail('长桥授权码兑换返回 HTTP ' + authResponse.status + '（授权码可能已过期，请重新生成）')
    const authRaw = await authResponse.text()
    let authPayload
    const authType = String(authResponse.headers.get('content-type') || '')
    if (authType.includes('text/event-stream')) {
      const frames = authRaw.split(/\r?\n\r?\n/); authPayload = null
      for (const frame of frames) for (const line of frame.split(/\r?\n/)) {
        if (!/^data:\s?/.test(line)) continue
        const data = line.replace(/^data:\s?/, '').trim()
        if (!data) continue
        try { const v = JSON.parse(data); if (v && v.id === 2) authPayload = v } catch { /* keep */ }
      }
      if (!authPayload) fail('长桥授权码兑换返回了无法解析的 SSE 响应')
    } else {
      try { authPayload = JSON.parse(authRaw) } catch { fail('长桥授权码兑换返回了无法解析的响应') }
    }
    if (authPayload.error) fail('长桥授权码无效：' + (authPayload.error.message || 'unknown') + '（授权码 10 分钟有效且仅可用一次）')
    const result = authPayload.result || {}
    if (result.isError) {
      const message = (result.content || []).map(c => c?.text || '').join(' ') || 'authenticate failed'
      fail('长桥授权码兑换失败：' + message)
    }
    const token = (result.structuredContent && (result.structuredContent.token || result.structuredContent.access_token || result.structuredContent.accessToken)) ||
      (() => { const c = (result.content || []).find(x => typeof x?.text === 'string'); if (!c) return null; try { const v = JSON.parse(c.text); return v.token || v.access_token || v.accessToken || null } catch { return /^[\w-]+\.[\w-]+\.[\w-]+$/.test(c.text.trim()) ? c.text.trim() : null } })()
    if (!token) fail('长桥授权响应中没有返回 Token，请重试或改用浏览器授权')
    return { token }
  } finally {
    clearTimeout(timer); signal?.removeEventListener('abort', onAbort)
  }
}

// ---------- snapshot ----------
// Map MCP account_balance + stock_positions + fund_positions (+ optional quote) to
// the canonical dsh-wealth snapshot. Prices come from quote when available; without
// them holdings keep manualPrice null and a PRICE_UNAVAILABLE warning.
const LB_AUTH_ERROR = /40[13]|授权|未授权|失效|过期|expired|unauthori[sz]ed|invalid.token|re-?auth/i
const MARKET_CASH_CURRENCY = { CN: 'CNY', HK: 'HKD', US: 'USD', SG: 'SGD' }
function stockHoldings(positions, warnings, seen) {
  const list = []
  let skipped = false
  for (const entry of array(positions, 'stock_positions list')) {
    const info = entry?.stock_info
    if (!info || typeof info !== 'object') { warnings.push('THS_LB_MCP_STOCK_ROW'); skipped = true; continue }
    for (const row of array(info, 'stock_positions.stock_info')) {
      const channel = entry?.account_channel && typeof entry.account_channel === 'string' ? entry.account_channel : ''
      const symbolRaw = String(row.symbol || '').trim()
      if (/\d{6}[CP]\d/i.test(symbolRaw)) throw new Error('长桥 MCP 返回了期权或衍生品持仓，本插件暂不支持：' + symbolRaw)
      const { symbol, market } = lbSymbol(symbolRaw, 'stock_positions.symbol')
      const key = market + ':' + symbol
      if (seen.has(key)) fail('长桥 MCP 返回了重复持仓 ' + symbol)
      seen.add(key)
      const qty = money(row.quantity, 'stock_positions.quantity')
      if (qty === 0) continue // 已清仓（当日卖光）：不是缺数据，旧持仓应随完整快照删除
      if (qty == null || qty < 0) { warnings.push('LB_MCP_MISSING_QTY:' + symbol); skipped = true; continue }
      const currencyValue = currency(row.currency || MARKET_CASH_CURRENCY[market] || 'USD', 'stock_positions.currency')
      // v1 契约要求 avgCost 必填：缺成本价时跳过该行并降级覆盖，绝不伪造成本。
      const cost = money(row.cost_price, 'stock_positions.cost_price')
      if (cost == null) { warnings.push('LB_MCP_COST_UNAVAILABLE:' + symbol); skipped = true; continue }
      list.push({
        symbol, name: typeof row.symbol_name === 'string' && row.symbol_name.trim() ? row.symbol_name.trim() : symbol,
        market, assetClass: market === 'CASH' ? 'cash' : 'stock',
        currency: currencyValue,
        qty, avgCost: cost,
        manualPrice: null, externalId: symbol, channel,
      })
    }
  }
  return { list, skipped }
}
function fundHoldings(positions, warnings, seen) {
  const list = []
  let skipped = false
  for (const entry of array(positions, 'fund_positions list')) {
    const info = entry?.fund_info
    if (!info || typeof info !== 'object') { warnings.push('LB_MCP_FUND_ROW'); skipped = true; continue }
    for (const row of array(info, 'fund_positions.fund_info')) {
      // counter_id like UT/FD/HK0000384492 — the last segment is the ISIN.
      const counterId = String(row.counter_id || '').trim()
      const last = counterId.split('/').pop() || counterId
      const symbol = last || fail('Longbridge MCP fund row has no counter_id')
      const key = 'FUND:' + symbol
      if (seen.has(key)) fail('长桥 MCP 返回了重复基金持仓 ' + symbol)
      seen.add(key)
      const qty = money(row.holding_units, 'fund_positions.holding_units')
      if (qty === 0) continue // 已清仓（当日卖光）：不是缺数据，旧持仓应随完整快照删除
      if (qty == null || qty < 0) { warnings.push('LB_MCP_MISSING_FUND_QTY:' + symbol); skipped = true; continue }
      const currencyValue = currency(row.currency || 'HKD', 'fund_positions.currency')
      const cost = money(row.cost_net_asset_value, 'fund_positions.cost_net_asset_value')
      if (cost == null) { warnings.push('LB_MCP_COST_UNAVAILABLE:' + symbol); skipped = true; continue }
      list.push({
        symbol, name: typeof row.symbol_name === 'string' && row.symbol_name.trim() ? row.symbol_name.trim() : symbol,
        market: 'FUND', assetClass: 'fund',
        currency: currencyValue,
        qty, avgCost: cost,
        manualPrice: money(row.current_net_asset_value, 'fund_positions.current_net_asset_value'),
        externalId: symbol, channel: entry?.account_channel && typeof entry.account_channel === 'string' ? entry.account_channel : '',
      })
    }
  }
  return { list, skipped }
}
function cashHoldings(balance, warnings) {
  const list = []
  let skipped = false
  for (const row of array(balance, 'account_balance')) {
    const infos = Array.isArray(row?.cash_infos) ? row.cash_infos : []
    for (const info of infos) {
      const c = currency(info?.currency || row?.currency, 'account_balance.cash_infos.currency')
      const available = money(info?.available_cash, 'available_cash')
      if (available == null) { warnings.push('LB_MCP_MISSING_CASH:' + c); skipped = true; continue }
      const frozen = money(info?.frozen_cash, 'frozen_cash') ?? 0
      const settling = money(info?.settling_cash, 'settling_cash') ?? 0
      const total = available + frozen + settling
      if (!(total > 0)) continue
      list.push({ symbol: `CASH:${c}`, name: `${c} cash`, market: 'CASH', assetClass: 'cash', currency: c, qty: total, avgCost: 1, manualPrice: 1, externalId: `CASH:${c}` })
    }
    if (!infos.length && money(row?.total_cash, 'account_balance.total_cash') != null) {
      warnings.push('LB_MCP_CASH_WITHOUT_COMPONENTS:' + (row?.currency || '?'))
      skipped = true
    }
  }
  return { list, skipped }
}
function pickChannel(list, source) {
  const wanted = source?.brokerAccountId && String(source.brokerAccountId) !== 'main' ? String(source.brokerAccountId) : null
  const channels = [...new Set(list.map(h => h.channel).filter(Boolean))]
  if (wanted && channels.length && !channels.includes(wanted)) fail('长桥 MCP 账户通道与连接配置不一致，请重新读取账户')
  const filtered = wanted && channels.length ? list.filter(h => !h.channel || h.channel === wanted) : list
  return { filtered, channels }
}
async function fetchQuotes(mcp, symbols, warnings) {
  if (!symbols.length) return new Map()
  const unique = [...new Set(symbols)].slice(0, 120)
  try {
    const quotes = await mcp.call('quote', { symbols: unique })
    const list = array(quotes, 'quote result')
    const map = new Map()
    for (const q of list) {
      if (!q?.symbol) continue
      const price = money(q.last_done, 'quote.last_done')
      if (price != null) map.set(String(q.symbol), price)
    }
    return map
  } catch (error) {
    warnings.push('LB_MCP_QUOTE_UNAVAILABLE:' + (error?.message || 'quote failed'))
    return new Map()
  }
}
export async function fetchLongbridgeMcpSnapshot(source, secrets, signal, deps = {}) {
  const mcp = createLongbridgeMcp({ secrets, endpoint: source?.mcpEndpoint, signal, deps })
  try {
    const warnings = []
    let coverageLost = false
    // 单个接口失败时降级为 partial（complete=false），保留账本里的旧持仓；
    // 只有全部来源都为空时才整体报错。
    const callOrWarn = async (tool, code) => {
      try { return await mcp.call(tool, {}) } catch (error) {
        // 认证失败必须抛出，交给上层续期/提示重新授权，不能降级成 partial。
        if (LB_AUTH_ERROR.test(String(error?.message || error))) throw error
        warnings.push(code + ':' + (error?.message || 'failed')); coverageLost = true; return [] }
    }
    const stocks = await callOrWarn('stock_positions', 'LB_MCP_POSITIONS_UNAVAILABLE')
    const funds = await callOrWarn('fund_positions', 'LB_MCP_FUND_POSITIONS_UNAVAILABLE')
    const balance = await callOrWarn('account_balance', 'LB_MCP_BALANCE_UNAVAILABLE')
    const seen = new Set()
    const stockResult = stockHoldings(stocks, warnings, seen)
    const fundResult = fundHoldings(funds, warnings, seen)
    const cashResult = cashHoldings(balance, warnings)
    if (stockResult.skipped || fundResult.skipped || cashResult.skipped) coverageLost = true
    const holdings = [...stockResult.list, ...fundResult.list, ...cashResult.list]
    if (!holdings.length) fail('长桥 MCP 没有返回任何持仓或现金；请确认账户内有资产或已授权对应权限')
    const { filtered } = pickChannel(holdings, source)
    const symbolQuotes = await fetchQuotes(mcp, filtered.filter(h => h.market !== 'CASH' && h.market !== 'FUND').map(h => h.symbol), warnings)
    let priced = 0
    for (const h of filtered) {
      if (h.market === 'CASH' || h.market === 'FUND') continue
      const price = symbolQuotes.get(h.symbol)
      if (price != null) { h.manualPrice = price; priced++ }
    }
    if (filtered.some(h => h.market !== 'CASH' && h.market !== 'FUND') && priced === 0) {
      warnings.push('PRICE_UNAVAILABLE:长桥行情接口未返回价格，证券按成本价暂估')
    }
    // 只有单一币种时才能由适配器求和；多币种直接省略合计（券商已折算的字段才原样保留）。
    const balanceRows = array(balance, 'account_balance')
    const balanceCurrencies = new Set(balanceRows.map(r => typeof r?.currency === 'string' && /^[A-Za-z]{3}$/.test(r.currency.trim()) ? r.currency.trim().toUpperCase() : null))
    const cashCurrencies = new Set(cashResult.list.map(h => h.currency))
    const singleBalance = balanceRows.length > 0 && balanceCurrencies.size === 1 && !balanceCurrencies.has(null)
    const singleCash = cashResult.list.length > 0 && cashCurrencies.size === 1
    const sourceTotals = {}
    if (singleBalance) {
      const netAssets = balanceRows.reduce((acc, row) => acc + (money(row?.net_assets, 'account_balance.net_assets') ?? 0), 0)
      if (netAssets) sourceTotals.netAssets = netAssets
    }
    if (singleBalance && singleCash) {
      const totalCash = balanceRows.reduce((acc, row) => acc + (money(row?.total_cash, 'account_balance.total_cash') ?? 0), 0)
      if (totalCash) sourceTotals.cash = totalCash
    }
    if ((!singleBalance && balanceRows.length > 1) || cashCurrencies.size > 1) {
      warnings.push('LB_MCP_MIXED_CURRENCY_TOTALS:多币种资产总额不做汇率折算，已省略合计')
    }
    const snapshot = {
      holdings: filtered.map(({ channel, ...rest }) => rest),
      // complete 只看覆盖：接口失败或有行因缺 qty/成本被跳过都不能删旧持仓；缺价不影响。
      complete: !coverageLost,
      warnings,
      queriedAt: new Date(deps.now?.() ?? Date.now()).toISOString(),
      uploadedAt: null, quoteDate: null,
      ...(Object.keys(sourceTotals).length ? { sourceTotals } : {}),
    }
    return snapshot
  } finally { await mcp.dispose() }
}

/** Account discovery for the MCP transport: exactly one synthetic 'main' account. */
export async function listLongbridgeMcpAccounts(source, secrets, signal, deps = {}) {
  const mcp = createLongbridgeMcp({ secrets, endpoint: source?.mcpEndpoint, signal, deps })
  try {
    const warnings = []
    const stocks = await mcp.call('stock_positions', {})
    const funds = await mcp.call('fund_positions', {})
    const hasStocks = array(stocks, 'stock_positions list').some(e => Array.isArray(e?.stock_info) && e.stock_info.length)
    const hasFunds = array(funds, 'fund_positions list').some(e => Array.isArray(e?.fund_info) && e.fund_info.length)
    if (!hasStocks && !hasFunds) warnings.push({ message: '长桥账户暂无股票/基金持仓，仍可导入现金' })
    return { accounts: [{ id: 'main', name: '长桥账户 · MCP', currency: null }], warnings }
  } finally { await mcp.dispose() }
}

// ---------- history ----------
// Currency is inferred from the market only as a fallback and always warns.
const FUND_CURRENCY_BY_MARKET = { HK: 'HKD', US: 'USD', CN: 'CNY', SG: 'SGD' }
function marketDefaultCurrency(market) { return marketCurrency(market) ?? FUND_CURRENCY_BY_MARKET[market] ?? null }
function mapExecutions(executions, warnings) {
  const rows = []
  for (const raw of array(executions, 'history_executions')) {
    const { symbol, market } = lbSymbol(raw?.symbol, 'history_executions.symbol')
    const side = String(raw?.side || '').trim().toLowerCase()
    if (!['buy', 'sell'].includes(side)) { warnings.push({ message: `LB_MCP_UNKNOWN_SIDE:${raw?.side || '?'}:${symbol}` }); continue }
    const qty = money(raw?.quantity, 'history_executions.quantity', { positive: true })
    const price = money(raw?.price, 'history_executions.price', { positive: true })
    const externalId = text(raw?.trade_id, 'history_executions.trade_id')
    const { date, time } = instant(raw?.trade_done_at, 'history_executions.trade_done_at')
    const currencyValue = raw?.currency ? currency(raw.currency, 'history_executions.currency') : (marketDefaultCurrency(market) ?? fail('Longbridge MCP 成交缺少币种且无法按市场推断'))
    if (!raw?.currency) warnings.push({ message: `CURRENCY_ASSUMED_FROM_MARKET:${symbol}:${currencyValue}` })
    rows.push(canonical({ ...{ date, time }, kind: side === 'buy' ? 'buy' : 'sell', originalType: side, symbol, market, currency: currencyValue, qty, price, cashAmount: null, fee: null, externalId, note: `Longbridge tradeId=${externalId}` }))
  }
  return rows
}
function mapCashFlow(flows, warnings) {
  const rows = []
  for (const raw of array(flows, 'cash_flow')) {
    const direction = String(raw?.direction || '').trim().toLowerCase()
    const business = String(raw?.business_type || '').trim()
    const description = String(raw?.description || '').trim()
    const label = `${business} ${description}`.toLowerCase()
    const amount = money(raw?.balance, 'cash_flow.balance', { signed: true })
    if (amount == null) { warnings.push({ message: 'LB_MCP_CASH_FLOW_NO_AMOUNT' }); continue }
    const currencyValue = currency(raw?.currency || 'CNY', 'cash_flow.currency')
    const when = instant(raw?.business_time, 'cash_flow.business_time')
    let kind = 'other'
    if (/dividend|股息|分红/.test(label)) kind = 'dividend'
    else if (/interest|利息/.test(label)) kind = 'interest'
    else if (/fee|费用|佣金|手续费/.test(label)) kind = 'fee'
    else if (/tax|税/.test(label)) kind = 'tax'
    else if (direction === 'in' && /存入|deposit|转入|入金/.test(label)) kind = 'deposit'
    else if (direction === 'out' && /取出|withdraw|转出|出金/.test(label)) kind = 'withdrawal'
    // Direction comes from the canonical registry; only 'other' falls back to the
    // source's own in/out flag because its economic meaning is unknown.
    const registrySign = cashSignOf(kind)
    const sign = typeof registrySign === 'number' ? registrySign : (kind === 'other' ? (direction === 'out' ? -1 : direction === 'in' ? 1 : null) : null)
    const symbolRaw = String(raw?.symbol || '').trim()
    let market = null, symbol = null
    if (symbolRaw) { try { const parsed = lbSymbol(symbolRaw); symbol = parsed.symbol; market = parsed.market } catch { symbol = symbolRaw } }
    rows.push(canonical({ ...when, kind, originalType: business || null, symbol, market, currency: currencyValue, qty: null, price: null, cashAmount: sign == null ? null : sign * Math.abs(amount), fee: null, externalId: null, note: `${raw?.transaction_flow_name || ''} ${description}`.trim() }))
  }
  return rows
}
export async function fetchLongbridgeMcpHistory(source, secrets, range, signal, deps = {}) {
  const from = day(range?.from, '开始日期'), to = day(range?.to, '结束日期')
  if (from > to) fail('开始日期不能晚于结束日期')
  const mcp = createLongbridgeMcp({ secrets, endpoint: source?.mcpEndpoint, signal, deps })
  try {
    const warnings = []
    const executions = mapExecutions(await mcp.call('history_executions', { start_at: from, end_at: to }), warnings)
    let flows = []
    try { flows = mapCashFlow(await mcp.call('cash_flow', { start_at: from, end_at: to }), warnings) } catch (error) {
      warnings.push({ message: 'LB_MCP_CASH_FLOW_UNAVAILABLE:' + (error?.message || 'cash_flow failed') })
    }
    const rows = dedupe([...executions, ...flows])
    if (rows.length > 25000) fail('长桥历史流水超过 25000 条，请按日期拆分回补')
    return {
      rows, errors: [], warnings,
      coverage: {
        complete: false,
        note: `已读取长桥 ${from} 至 ${to} 的成交与资金流水；未成交的订单、费用分摊和部分公司行为可能缺失，可用券商账单文件补充。`,
        observedFrom: rows.length ? rows[0].date : null, observedTo: rows.length ? rows[rows.length - 1].date : null,
      },
    }
  } finally { await mcp.dispose() }
}

/** One-time agent-code exchange is verified by attempting an initialize+list on /mcp. */
export async function verifyLongbridgeMcpToken(token, { endpoint, signal, deps = {} } = {}) {
  const mcp = createLongbridgeMcp({ secrets: { mcpToken: token }, endpoint, signal, deps })
  try { await mcp.call('now', {}) ; return true } finally { await mcp.dispose() }
}

export function longbridgeMcpFingerprintPart(secrets = {}) {
  const token = String(secrets?.mcpToken || '')
  return token ? createHash('sha256').update(token).digest('hex').slice(0, 16) : ''
}
